function test_shareAmountToBeBurnedAndProfitCanBeIncorrect() public {
        uint256 _amount = 10_000 * 1e6;

        _dealWhale(baseToken, address(alice), address(0x1AB4973a48dc892Cd9971ECE8e01DcC7688f8F23), 10 * _amount);

        vm.startPrank(alice);
        SafeERC20.forceApprove(IERC20(USDC), address(accountingManager), 6 * _amount);
        accountingManager.deposit(address(alice), 6 * _amount, address(0));

        uint256 USDCAfterDepositAlice = IERC20(USDC).balanceOf(address(alice));

        // after Alice deposits 6 * _amount USDC, accountingManager has no profit
        uint256 profitAfterDeposit = accountingManager.getProfit();
        assertEq(profitAfterDeposit, 0);

        vm.startPrank(owner);
        accountingManager.calculateDepositShares(10);

        vm.warp(block.timestamp + 35 minutes);
        accountingManager.executeDeposit(10, connector2, "");

        // Alice withdraws all of her shares
        vm.startPrank(alice);
        accountingManager.withdraw(6 * _amount, address(alice));

        vm.startPrank(owner);
        accountingManager.calculateWithdrawShares(10);

        vm.warp(block.timestamp + 6 hours + 5 minutes);
        accountingManager.startCurrentWithdrawGroup();

        // retrieveTokensForWithdraw function is called
        //   with retrieveData input that has 6 * _amount as asked amount for withdrawal and _amount as actual amount for withdrawal
        RetrieveData[] memory retrieveData = new RetrieveData[](1);
        retrieveData[0] = RetrieveData(6 * _amount, address(connector2), abi.encode(_amount, _amount));
        accountingManager.retrieveTokensForWithdraw(retrieveData);

        accountingManager.fulfillCurrentWithdrawGroup();
        accountingManager.executeWithdraw(10);

        // Alice burns all of her shares but only receives _amount USDC.
        // When it is just temporary that actual amount must be less than asked amount for withdrawal at this moment,
        //   even if actual amount could be increased to cover all of asked amount for withdrawal in future,
        //   Alice cannot withdraw remaining part of 6 * _amount that was not withdrawn previously, which she is entitled to,
        //   since all of her shares were burned already.
        assertEq(accountingManager.balanceOf(address(alice)), 0);
        assertEq(IERC20(USDC).balanceOf(address(alice)) - USDCAfterDepositAlice, _amount);

        // since 6 * _amount USDC was deposited but only _amount USDC was withdrawn, accountingManager should not have any profit
        //   but accountingManager has 5 * _amount profit incorrectly
        assertEq(accountingManager.getProfit() - profitAfterDeposit, 6 * _amount - _amount);
    }

