    address basePriceFeed = comet.baseTokenPriceFeed();
    uint256 basePriceInVirtualBase = comet.getPrice(basePriceFeed);
    borrowBalanceInVirtualBase = (borrowBalanceInBase * basePriceInVirtualBase) / comet.baseScale();
}

