    if (swapParams.direction == SwapDirection.EXACT_OUT) {
        _refundUser(
            refund,
            swapParams.tokenIn,
            swapParams.amountIn - swapParams.amountOut
        );
    }

    uint amt2Recipient = swapParams.direction == SwapDirection.EXACT_OUT
