function callBridge(
    uint256 amt2Bridge,
    uint256 dstChainId,
    bytes memory bridgePayload,
    bytes calldata additionalArgs,
    address payable refund
) private {
    router.swap{value: msg.value}(
        getDstChainId(additionalArgs), //lzBridgeData._dstChainId, // send to LayerZero chainId
        getSrcPoolId(additionalArgs), //lzBridgeData._srcPoolId, // source pool id
        getDstPoolId(additionalArgs), //lzBridgeData._dstPoolId, // dst pool id
        refund, // refund adddress. extra gas (if any) is returned to this address
        amt2Bridge, // quantity to swap
        (amt2Bridge * (10000 - SG_FEE_BPS)) / 10000, // the min qty you would accept on the destination, fee is 6 bips
        getLzTxObj(additionalArgs), // additional gasLimit increase, airdrop, at address
        abi.encodePacked(getDestAdapter(dstChainId)),
        bridgePayload // bytes param, if you wish to send additional payload you can abi.encode() them here
    );
}

function swapAndModifyPostBridge(
    BridgeInstructions memory instructions
)
    private
    returns (
        uint256 amount2Bridge,
        BridgeInstructions memory updatedInstructions
    )
{
    (address tokenOut, uint256 amountOut) = performSwap(
        instructions.preBridge
    );

    SwapParams memory newPostSwapParams = abi.decode(
        instructions.postBridge.swapPayload,
        (SwapParams)
    );

    newPostSwapParams.amountIn = IBridgeAdapter(
        bridgeAdapters[instructions.bridgeId]
    ).getBridgedAmount(amountOut, tokenOut, newPostSwapParams.tokenIn);

    updatedInstructions = instructions;

    updatedInstructions.postBridge.swapPayload = ISwapper(swappers[
        instructions.postBridge.swapperId
    ]).updateSwapParams(
        newPostSwapParams,
        instructions.postBridge.swapPayload
    );

    amount2Bridge = amountOut;
}

