    // Pull in the old tokens
    TokenUtils.safeTransferFrom(bridgeTokenAddress, msg.sender, address(this), tokenAmount);

    // Handle the fee, if applicable
    canonicalTokensOut = tokenAmount;
    if (!_isFeeExempt(msg.sender)) {
