function _updateAccount(UpdateAccountParams memory params) internal {
  Account storage account = accounts[params.owner];

  UpdateAccountCache memory cache = UpdateAccountCache({
    unexchangedBalance: account.unexchangedBalance,
    exchangedBalance: account.exchangedBalance,
    occupiedTick: account.occupiedTick,
    totalUnexchanged: totalUnexchanged,
    currentTick: ticks.position
  });

  UpdateAccountState memory state = UpdateAccountState({
    unexchangedBalance: cache.unexchangedBalance,
    exchangedBalance: cache.exchangedBalance,
    totalUnexchanged: cache.totalUnexchanged
  });

  // Updating an account is broken down into five steps:
  // 1). Synchronize the account if it previously occupied a satisfied tick
  // 2). Update the account balances to account for exchanged tokens, if any
  // 3). Apply the deltas to the account balances
  // 4). Update the previously occupied and or current tick's liquidity
  // 5). Commit changes to the account and global state when needed

  // Step one:
  // ---------
  // Check if the tick that the account was occupying previously was satisfied. If it was, we acknowledge
  // that all of the tokens were exchanged.
  if (state.unexchangedBalance > 0 && satisfiedTick >= cache.occupiedTick) {
    state.unexchangedBalance = 0;
    state.exchangedBalance += cache.unexchangedBalance;
  }

  // Step Two:
  // ---------
  // Calculate how many tokens were exchanged since the last update.
  if (state.unexchangedBalance > 0) {
    uint256 exchanged = LiquidityMath.calculateProduct(
      state.unexchangedBalance,
      ticks.getWeight(cache.occupiedTick, cache.currentTick)
    );

    state.totalUnexchanged -= exchanged;
    state.unexchangedBalance -= exchanged;
    state.exchangedBalance += exchanged;
  }

  // Step Three:
  // -----------
  // Apply the unexchanged and exchanged deltas to the state.
  state.totalUnexchanged = LiquidityMath.addDelta(state.totalUnexchanged, params.unexchangedDelta);
  state.unexchangedBalance = LiquidityMath.addDelta(state.unexchangedBalance, params.unexchangedDelta);
  state.exchangedBalance = LiquidityMath.addDelta(state.exchangedBalance, params.exchangedDelta);

  // Step Four:
  // ----------
  // The following is a truth table relating various values which in combinations specify which logic branches
  // need to be executed in order to update liquidity in the previously occupied and or current tick.
  //
  // Some states are not obtainable and are just discarded by setting all the branches to false.
  //
  // | P | C | M | Modify Liquidity | Add Liquidity | Subtract Liquidity |
  // |---|---|---|------------------|---------------|--------------------|
  // | F | F | F | F                | F             | F                  |
  // | F | F | T | F                | F             | F                  |
  // | F | T | F | F                | T             | F                  |
  // | F | T | T | F                | T             | F                  |
  // | T | F | F | F                | F             | T                  |
  // | T | F | T | F                | F             | T                  |
  // | T | T | F | T                | F             | F                  |
  // | T | T | T | F                | T             | T                  |
  //
  // | Branch             | Reduction |
  // |--------------------|-----------|
  // | Modify Liquidity   | PCM'      |
  // | Add Liquidity      | P'C + CM  |
  // | Subtract Liquidity | PC' + PM  |

  bool previouslyActive = cache.unexchangedBalance > 0;
  bool currentlyActive = state.unexchangedBalance > 0;
  bool migrate = cache.occupiedTick != cache.currentTick;

  bool modifyLiquidity = previouslyActive && currentlyActive && !migrate;

  if (modifyLiquidity) {
    Tick.Info storage tick = ticks.get(cache.occupiedTick);

    // Consolidate writes to save gas.
    uint256 totalBalance = tick.totalBalance;
    totalBalance -= cache.unexchangedBalance;
    totalBalance += state.unexchangedBalance;
    tick.totalBalance = totalBalance;
  } else {
    bool addLiquidity = (!previouslyActive && currentlyActive) || (currentlyActive && migrate);
    bool subLiquidity = (previouslyActive && !currentlyActive) || (previouslyActive && migrate);

    if (addLiquidity) {
      Tick.Info storage tick = ticks.get(cache.currentTick);

      if (tick.totalBalance == 0) {
        ticks.addLast(cache.currentTick);
      }

      tick.totalBalance += state.unexchangedBalance;
    }

    if (subLiquidity) {
      Tick.Info storage tick = ticks.get(cache.occupiedTick);
      tick.totalBalance -= cache.unexchangedBalance;

      if (tick.totalBalance == 0) {
        ticks.remove(cache.occupiedTick);
      }
    }
  }

  // Step Five:
  // ----------
  // Commit the changes to the account.
  if (cache.unexchangedBalance != state.unexchangedBalance) {
    account.unexchangedBalance = state.unexchangedBalance;
  }

  if (cache.exchangedBalance != state.exchangedBalance) {
    account.exchangedBalance = state.exchangedBalance;
  }

  if (cache.totalUnexchanged != state.totalUnexchanged) {
    totalUnexchanged = state.totalUnexchanged;
  }

  if (cache.occupiedTick != cache.currentTick) {
    account.occupiedTick = cache.currentTick;
  }
}

function _alchemistAction(
    uint256 amount,
    address weightToken,
    function(address, uint256) action
) internal {
    IAlchemistV2(alchemist).poke(address(this));

    Weighting storage weighting = weightings[weightToken];
    for (uint256 j = 0; j < weighting.tokens.length; j++) {
        address token = weighting.tokens[j];
        uint256 actionAmt = (amount * weighting.weights[token]) / weighting.totalWeight;
        action(token, actionAmt);
    }
}

function _alchemistAction(
    uint256 amount,
    address weightToken,
    function(address, uint256) action
) internal {
    IAlchemistV2(alchemist).poke(address(this));

    Weighting storage weighting = weightings[weightToken];
    for (uint256 j = 0; j < weighting.tokens.length; j++) {
        address token = weighting.tokens[j];
        uint256 actionAmt = (amount * weighting.weights[token]) / weighting.totalWeight;
        action(token, actionAmt);
    }
}

if (msg.sender != alchemist) {
    revert Unauthorized("Not alchemist");
}

receive() external payable {
    if (msg.sender != underlyingToken && msg.sender != token) {
        revert Unauthorized("Payments only permitted from WETH or rETH");
    }
}

constructor(InitializationParams memory params) {
    alchemist       = params.alchemist;
    token           = params.token;
    parentToken     = params.parentToken;
    underlyingToken = params.underlyingToken;
    curvePool       = params.curvePool;
    ethPoolIndex    = params.ethPoolIndex;
    stEthPoolIndex  = params.stEthPoolIndex;
    referral        = params.referral;

    // Verify and make sure that the provided ETH matches the curve pool ETH.
    if (
        IStableSwap2Pool(params.curvePool).coins(params.ethPoolIndex) !=
        0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE
    ) {
        revert IllegalArgument("Curve pool ETH token mismatch");
    }

    // Verify and make sure that the provided stETH matches the curve pool stETH.
    if (
        IStableSwap2Pool(params.curvePool).coins(params.stEthPoolIndex) !=
        params.parentToken
    ) {
        revert IllegalArgument("Curve pool stETH token mismatch");
    }
}

if (msg.sender != alchemist) {
    revert Unauthorized("Not alchemist");
}

function _calculateUnlockedCredit(address yieldToken) internal view returns (uint256) {
    YieldTokenParams storage yieldTokenParams = _yieldTokens[yieldToken];

    uint256 pendingCredit = yieldTokenParams.pendingCredit;
    if (pendingCredit == 0) {
        return 0;
    }

    uint256 creditUnlockRate      = yieldTokenParams.creditUnlockRate;
    uint256 distributedCredit     = yieldTokenParams.distributedCredit;
    uint256 lastDistributionBlock = yieldTokenParams.lastDistributionBlock;

    uint256 percentUnlocked = (block.number - lastDistributionBlock) * creditUnlockRate;

    return percentUnlocked < FIXED_POINT_SCALAR
        ? (pendingCredit * percentUnlocked / FIXED_POINT_SCALAR) - distributedCredit
        : pendingCredit - distributedCredit;
}

function _transferTokensToSelf(address underlyingToken, uint256 collateralInitial) internal override {
    if (msg.value > 0) revert IllegalArgument("msg.value should be 0");
    IERC20(underlyingToken).transferFrom(msg.sender, address(this), collateralInitial);
}

function _transferTokensToSelf(address underlyingToken, uint256 collateralInitial) internal override {
    // Convert eth to weth if received eth, otherwise transfer weth
    if (msg.value > 0) {
        if (msg.value != collateralInitial) revert IllegalArgument("msg.value doesn't match collateralInitial");
        IWETH9(wethAddress).deposit{value: msg.value}();
    } else {
        IERC20(underlyingToken).transferFrom(msg.sender, address(this), collateralInitial);
    }
}

function _deposit(uint256 _poolId, uint256 _depositAmount) internal {
  Pool.Data storage _pool = _pools.get(_poolId);
  Stake.Data storage _stake = _stakes[msg.sender][_poolId];

  _pool.totalDeposited = _pool.totalDeposited + _depositAmount;
  _stake.totalDeposited = _stake.totalDeposited + _depositAmount;

  _pool.token.safeTransferFrom(msg.sender, address(this), _depositAmount);

  emit TokensDeposited(msg.sender, _poolId, _depositAmount);
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 balanceBeforeUnderlying = IERC20(underlyingToken).balanceOf(address(this));
    uint256 balanceBeforeYieldToken = IERC20(token).balanceOf(address(this));

    // Vesper withdraw does not accept a recipient argument and does not return withdrawn amount
    IVesperPool(token).withdraw(amount);

    uint256 balanceAfterUnderlying = IERC20(underlyingToken).balanceOf(address(this));
    uint256 balanceAfterYieldToken = IERC20(token).balanceOf(address(this));

    uint256 withdrawn = balanceAfterUnderlying - balanceBeforeUnderlying;

    if (balanceBeforeYieldToken - balanceAfterYieldToken != amount) {
        revert IllegalState("Not all shares were burned");
    }

    // We must transfer to recipient after and use IERC20.balanceOf() for amount
    SafeERC20.safeTransfer(underlyingToken, recipient, withdrawn);

    return withdrawn;
}

function wrap(
    uint256 amount,
    address recipient
) external onlyAlchemist returns (uint256) {
    // Transfer the underlying tokens from the message sender.
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    SafeERC20.safeApprove(underlyingToken, token, amount);

    uint256 balanceBefore = IERC20(token).balanceOf(address(this));

    // Vesper deposit does not accept a recipient argument and does not return mint amount
    IVesperPool(token).deposit(amount);

    uint256 balanceAfter = IERC20(token).balanceOf(address(this));

    uint256 minted = balanceAfter - balanceBefore;

    // We must transfer to recipient after and use IERC20.balanceOf() for amount
    SafeERC20.safeTransfer(token, recipient, minted);

    return minted;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the rETH from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    // Burn the rETH to receive ETH.
    uint256 startingEthBalance = address(this).balance;
    IRETH(token).burn(amount);
    uint256 receivedEth = address(this).balance - startingEthBalance;

    // Wrap the ETH that we received from the burn.
    IWETH9(underlyingToken).deposit{value: receivedEth}();

    // Transfer the tokens to the recipient.
    SafeERC20.safeTransfer(underlyingToken, recipient, receivedEth);

    return receivedEth;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    // Unwrap the wstETH into stETH.
    uint256 startingStEthBalance = IStETH(parentToken).balanceOf(address(this));
    IWstETH(token).unwrap(amount);
    uint256 endingStEthBalance = IStETH(parentToken).balanceOf(address(this));

    // Approve the curve pool to transfer the tokens.
    uint256 unwrappedStEth = endingStEthBalance - startingStEthBalance;
    SafeERC20.safeApprove(parentToken, curvePool, unwrappedStEth);

    // Exchange the stETH for ETH. We do not check the curve pool because it is an immutable
    // contract and we expect that its output is reliable.
    uint256 received = IStableSwap2Pool(curvePool).exchange(
        int128(uint128(stEthPoolIndex)), // Why are we here, just to suffer?
        int128(uint128(ethPoolIndex)),   //                       (╥﹏╥)
        unwrappedStEth,
        0                                // <- Slippage is handled upstream
    );

    // Wrap the ETH that we received from the exchange.
    IWETH9(underlyingToken).deposit{value: received}();

    // Transfer the tokens to the recipient.
    SafeERC20.safeTransfer(underlyingToken, recipient, received);

    return received;
}

function wrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    // Transfer the tokens from the message sender.
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);

    // Unwrap the WETH into ETH.
    IWETH9(underlyingToken).withdraw(amount);

    // Wrap the ETH into stETH.
    uint256 startingStEthBalance = IERC20(token).balanceOf(address(this));

    IStETH(parentToken).submit{value: amount}(referral);

    uint256 mintedStEth = IERC20(parentToken).balanceOf(address(this)) - startingStEthBalance;

    // Wrap the stETH into wstETH.
    SafeERC20.safeApprove(parentToken, address(token), mintedStEth);
    uint256 mintedWstEth = IWstETH(token).wrap(mintedStEth);

    // Transfer the minted wstETH to the recipient.
    SafeERC20.safeTransfer(token, recipient, mintedWstEth);

    return mintedWstEth;
}

function unwrap(
    uint256 amount,
    address recipient
) external lock onlyAlchemist returns (uint256) {
    SafeERC20.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 startingBalance = IERC20(underlyingToken).balanceOf(address(this));

    uint256 error;
    if ((error = ICERC20(token).redeem(amount)) != NO_ERROR) {
        revert FuseError(error);
    }

    uint256 endingBalance = IERC20(underlyingToken).balanceOf(address(this));
    uint256 redeemedAmount = endingBalance - startingBalance;

    SafeERC20.safeTransfer(underlyingToken, recipient, redeemedAmount);

    return redeemedAmount;
}

function wrap(
    uint256 amount,
    address recipient
) external onlyAlchemist returns (uint256) {
    SafeERC20.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    SafeERC20.safeApprove(underlyingToken, token, amount);

    uint256 startingBalance = IERC20(token).balanceOf(address(this));

    uint256 error;
    if ((error = ICERC20(token).mint(amount)) != NO_ERROR) {
        revert FuseError(error);
    }

    uint256 endingBalance = IERC20(token).balanceOf(address(this));
    uint256 mintedAmount = endingBalance - startingBalance;

    SafeERC20.safeTransfer(token, recipient, mintedAmount);

    return mintedAmount;
}

function unwrap(uint256 amount, address recipient) external override returns (uint256) {
    TokenUtils.safeTransferFrom(token, msg.sender, address(this), amount);

    uint256 balanceBefore = TokenUtils.safeBalanceOf(token, address(this));

    uint256 amountWithdrawn = IYearnVaultV2(token).withdraw(amount, recipient, MAXIMUM_SLIPPAGE);

    uint256 balanceAfter = TokenUtils.safeBalanceOf(token, address(this));

    // If the Yearn vault did not burn all of the shares then revert. This is critical in mathematical operations
    // performed by the system because the system always expects that all of the tokens were unwrapped. In Yearn,
    // this sometimes does not happen in cases where strategies cannot withdraw all of the requested tokens (an
    // example strategy where this can occur is with Compound and AAVE where funds may not be accessible because
    // they were lent out).
    if (balanceBefore - balanceAfter != amount) {
        revert IllegalState();
    }

    return amountWithdrawn;
}

function wrap(uint256 amount, address recipient) external override returns (uint256) {
    TokenUtils.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    TokenUtils.safeApprove(underlyingToken, token, amount);

    return IYearnVaultV2(token).deposit(amount, recipient);
}

function deposit(uint256 amount, address owner) external override nonReentrant {
  _onlyWhitelisted();
  _updateAccount(
    UpdateAccountParams({
      owner: owner,
      unexchangedDelta: SafeCast.toInt256(amount),
      exchangedDelta: 0
    })
  );
  TokenUtils.safeTransferFrom(syntheticToken, msg.sender, address(this), amount);
  emit Deposit(msg.sender, owner, amount);
}

function repay(address underlyingToken, uint256 amount, address recipient) external override lock returns (uint256) {
    _onlyWhitelisted();

    _checkArgument(amount > 0);
    _checkArgument(recipient != address(0));

    _checkSupportedUnderlyingToken(underlyingToken);
    _checkUnderlyingTokenEnabled(underlyingToken);

    // Distribute unlocked credit to depositors.
    _distributeUnlockedCreditDeposited(recipient);

    // Update the recipient's account and decrease the amount of debt incurred.
    _poke(recipient);

    // Check that the debt is greater than zero.
    //
    // It is possible that the amount of debt which is repayable is equal to or less than zero after realizing the
    // credit that was earned since the last update. We do not want to perform a noop so we need to check that the
    // amount of debt to repay is greater than zero.
    int256 debt;
    _checkState((debt = _accounts[recipient].debt) > 0);

    // Determine the maximum amount of underlying tokens that can be repaid.
    //
    // It is implied that this value is greater than zero because `debt` is greater than zero so a noop is not possible
    // beyond this point. Casting the debt to an unsigned integer is also safe because `debt` is greater than zero.
    uint256 maximumAmount = _normalizeDebtTokensToUnderlying(underlyingToken, uint256(debt));

    // Limit the number of underlying tokens to repay up to the maximum allowed.
    uint256 actualAmount = amount > maximumAmount ? maximumAmount : amount;

    Limiters.LinearGrowthLimiter storage limiter = _repayLimiters[underlyingToken];

    // Check to make sure that the underlying token repay limit has not been breached.
    uint256 currentRepayLimit = limiter.get();
    if (actualAmount > currentRepayLimit) {
      revert RepayLimitExceeded(underlyingToken, actualAmount, currentRepayLimit);
    }

    uint256 credit = _normalizeUnderlyingTokensToDebt(underlyingToken, actualAmount);

    // Update the recipient's debt.
    _updateDebt(recipient, -SafeCast.toInt256(credit));

    // Decrease the amount of the underlying token which is globally available to be repaid.
    limiter.decrease(actualAmount);

    // Transfer the repaid tokens to the transmuter.
    TokenUtils.safeTransferFrom(underlyingToken, msg.sender, transmuter, actualAmount);

    // Inform the transmuter that it has received tokens.
    IERC20TokenReceiver(transmuter).onERC20Received(underlyingToken, actualAmount);

    emit Repay(msg.sender, underlyingToken, actualAmount, recipient);

    return actualAmount;
}

function _wrap(
    address yieldToken,
    uint256 amount,
    uint256 minimumAmountOut
) internal returns (uint256) {
    YieldTokenParams storage yieldTokenParams = _yieldTokens[yieldToken];

    ITokenAdapter adapter = ITokenAdapter(yieldTokenParams.adapter);
    address underlyingToken = yieldTokenParams.underlyingToken;

    TokenUtils.safeTransferFrom(underlyingToken, msg.sender, address(this), amount);
    uint256 wrappedShares = adapter.wrap(amount, address(this));
    if (wrappedShares < minimumAmountOut) {
        revert SlippageExceeded(wrappedShares, minimumAmountOut);
    }

    return wrappedShares;
}

function deposit(
    address yieldToken,
    uint256 amount,
    address recipient
) external override lock returns (uint256) {
    _onlyWhitelisted();
    _checkArgument(recipient != address(0));
    _checkSupportedYieldToken(yieldToken);

    // Deposit the yield tokens to the recipient.
    uint256 shares = _deposit(yieldToken, amount, recipient);

    // Transfer tokens from the message sender now that the internal storage updates have been committed.
    TokenUtils.safeTransferFrom(yieldToken, msg.sender, address(this), amount);

    return shares;
}

/// @notice A set of addresses which are whitelisted for minting new tokens.
mapping(address => bool) public whitelisted;

/// @notice A set of addresses which are paused from minting new tokens.
mapping(address => bool) public paused;

function maxFlashLoan(address token) public view override returns (uint256) {
  if (token != address(this)) {
    return 0;
  }
  return maxFlashLoanAmount;
}

function flashFee(address token, uint256 amount) public view override returns (uint256) {
  if (token != address(this)) {
    revert IllegalArgument();
  }
  return amount * flashMintFee / BPS;
}

function flashLoan(
  IERC3156FlashBorrower receiver,
  address token,
  uint256 amount,
  bytes calldata data
) external override nonReentrant returns (bool) {
  if (token != address(this)) {
    revert IllegalArgument();
  }

  if (amount > maxFlashLoan(token)) {
    revert IllegalArgument();
  }

  uint256 fee = flashFee(token, amount);

  _mint(address(receiver), amount);

  if (receiver.onFlashLoan(msg.sender, token, amount, fee, data) != CALLBACK_SUCCESS) {
    revert IllegalState();
  }

  _burn(address(receiver), amount + fee); // Will throw error if not enough to burn

  return true;
}

